import{_ as h,o as t,c,a2 as g}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"&quot;Học kỹ&quot; nghĩa là gì, và dừng ở đâu","description":"","frontmatter":{},"headers":[],"relativePath":"learning/hoc-ky.md","filePath":"learning/hoc-ky.md"}'),i={name:"learning/hoc-ky.md"};function a(o,n,u,r,m,e){return t(),c("div",null,[...n[0]||(n[0]=[g('<h1 id="quot-hoc-ky-quot-nghia-la-gi-va-dung-o-đau" tabindex="-1">&quot;Học kỹ&quot; nghĩa là gì, và dừng ở đâu <a class="header-anchor" href="#quot-hoc-ky-quot-nghia-la-gi-va-dung-o-đau" aria-label="Permalink to &quot;&amp;quot;Học kỹ&amp;quot; nghĩa là gì, và dừng ở đâu&quot;">​</a></h1><p>Trên trang này# &quot;Học kỹ&quot; nghĩa là gì, và dừng ở đâu <a href="#hoc-ky-nghia-la-gi-va-dung-o-đau">​</a> Ai cũng muốn con &quot;học kỹ&quot;. Rất ít người định nghĩa được nó, và gần như không ai nói về chỗ nên dừng. Nhưng chính chỗ dừng mới quyết định thời gian của một đứa trẻ được dùng tốt hay bị phí.</p><h2 id="hoc-ky-la-mot-muc-khong-phai-mot-cam-giac-​" tabindex="-1">Học kỹ là một mức, không phải một cảm giác <a href="#hoc-ky-la-mot-muc-khong-phai-mot-cam-giac">​</a> <a class="header-anchor" href="#hoc-ky-la-mot-muc-khong-phai-mot-cam-giac-​" aria-label="Permalink to &quot;Học kỹ là một mức, không phải một cảm giác [​](#hoc-ky-la-mot-muc-khong-phai-mot-cam-giac)&quot;">​</a></h2><p>&quot;Con đã học kỹ chưa?&quot; là câu hỏi không trả lời được nếu không nói rõ <strong>kỹ đến mức nào</strong>. Nemo12 dùng sáu bậc sâu: BậcLearner làm được gì<strong>L0 — Exposure</strong>Đã gặp qua khái niệm này<strong>L1 — Recognition</strong>Nhận ra khi được nhắc, chọn đúng trong các phương án<strong>L2 — Basic Application</strong>Làm được bài quen thuộc, đúng dạng đã học<strong>L3 — Independent Application</strong>Tự làm được bài mới cùng loại, không cần gợi ý<strong>L4 — Transfer</strong>Dùng được kiến thức này trong tình huống lạ, đề hỏi kiểu khác<strong>L5 — Deep Mastery</strong>Giải thích được cho người khác, nối được với các mảng kiến thức khácMột học sinh lớp 7 học chương trình phổ thông cần tới <strong>L3</strong> cho phần lớn nội dung. Một học sinh ôn thi chuyên cần <strong>L4–L5</strong> ở những mảng trọng tâm — nhưng vẫn chỉ cần L2–L3 ở những mảng ngoại vi. Điểm quan trọng: <strong>L5 ở mọi thứ không phải mục tiêu đáng theo đuổi</strong>. Nó bất khả thi về thời gian, và phần lớn giá trị nằm ở việc phân bổ đúng chỗ nào cần sâu.</p><h2 id="ba-con-so-cho-moi-muc-tieu-​" tabindex="-1">Ba con số cho mỗi mục tiêu <a href="#ba-con-so-cho-moi-muc-tieu">​</a> <a class="header-anchor" href="#ba-con-so-cho-moi-muc-tieu-​" aria-label="Permalink to &quot;Ba con số cho mỗi mục tiêu [​](#ba-con-so-cho-moi-muc-tieu)&quot;">​</a></h2><p>Với mỗi mảng kiến thức, Nemo12 đặt trước ba ngưỡng:</p><ul><li><strong>Bậc sâu cần đạt</strong> — L3? L4?</li><li><strong>Mức vững mong muốn</strong> — 0.80? 0.90?</li><li><strong>Độ chắc chắn tối thiểu của kết luận</strong> — hệ thống phải tin vào đánh giá của mình tới mức nào trước khi tuyên bố đã đạt. Con số thứ ba hay bị bỏ quên nhưng lại quan trọng nhất. &quot;Mức vững 0.85 nhưng độ chắc chắn 0.20&quot; nghĩa là <em>có vẻ con giỏi, nhưng chưa đủ bằng chứng để nói chắc</em> — và đó là trạng thái hoàn toàn khác với &quot;con giỏi&quot;.</li></ul><h2 id="he-thong-dung-khi-nao-​" tabindex="-1">Hệ thống dừng khi nào <a href="#he-thong-dung-khi-nao">​</a> <a class="header-anchor" href="#he-thong-dung-khi-nao-​" aria-label="Permalink to &quot;Hệ thống dừng khi nào [​](#he-thong-dung-khi-nao)&quot;">​</a></h2><p>Bốn điều kiện phải cùng đúng: textmức vững ≥ ngưỡng độ chắc chắn ≥ ngưỡng bậc sâu ≥ bậc yêu cầu bằng chứng đủ đa dạng (nhiều loại, nhiều thời điểm, nhiều ngữ cảnh)Điều kiện cuối chống lại một cái bẫy tinh vi: mười câu đúng liên tiếp <em>cùng một dạng</em> nghe rất thuyết phục, nhưng nó chỉ chứng minh learner làm được dạng đó. Bằng chứng đa dạng mới phân biệt được hiểu và thuộc.</p><h2 id="va-he-thong-dung-ca-khi-chua-đat-​" tabindex="-1">Và hệ thống dừng cả khi chưa đạt <a href="#va-he-thong-dung-ca-khi-chua-đat">​</a> <a class="header-anchor" href="#va-he-thong-dung-ca-khi-chua-đat-​" aria-label="Permalink to &quot;Và hệ thống dừng cả khi chưa đạt [​](#va-he-thong-dung-ca-khi-chua-đat)&quot;">​</a></h2><p>Đây là phần ít ai làm, và là phần khiến Nemo12 khác biệt. <strong>Lợi ích giảm dần.</strong> Khi mỗi giờ thêm chỉ còn đẩy được một chút, trong khi có một mảng khác đang yếu hơn nhiều, hệ thống <strong>chuyển learner sang mảng kia</strong> — dù mảng hiện tại chưa chạm ngưỡng. Mục tiêu không phải tối đa hoá từng mảng, mà tối đa hoá tổng thể trong quỹ thời gian có thật. <strong>Chống học thừa.</strong> Hệ thống chủ động phát hiện ba tình huống: luyện lại thứ đã rất chắc; đào sâu phần không phục vụ mục tiêu nào; học nâng cao trong khi vẫn còn lỗ hổng nền nghiêm trọng ở chỗ khác. Cả ba đều bị hạ ưu tiên. Câu hỏi trung tâm Không phải <em>&quot;học sâu thêm ở đây có tốt không?&quot;</em> — gần như luôn tốt. Mà là: <strong>&quot;học sâu thêm ở đây có còn là cách dùng thời gian tốt nhất của con lúc này không?&quot;</strong></p><h2 id="ban-co-quyen-khong-đong-y-​" tabindex="-1">Bạn có quyền không đồng ý <a href="#ban-co-quyen-khong-đong-y">​</a> <a class="header-anchor" href="#ban-co-quyen-khong-đong-y-​" aria-label="Permalink to &quot;Bạn có quyền không đồng ý [​](#ban-co-quyen-khong-đong-y)&quot;">​</a></h2><p>Khi một gia đình muốn đẩy một mảng từ L3 lên L4, Nemo12 không từ chối. Hệ thống cho bạn thấy <strong>cái giá</strong>: cần khoảng 4–6 giờ nữa, và 4–6 giờ đó sẽ lấy từ đâu. Đó là quyết định của gia đình, không phải của hệ thống. Việc của Nemo12 là làm cho sự đánh đổi trở nên nhìn thấy được — vì thời gian học của một đứa trẻ luôn là trò chơi tổng không đổi, kể cả khi không ai nói ra điều đó. &quot;Học kỹ&quot; là một mức được chọn có chủ đích, kèm cái giá đã biết. Không phải &quot;học tới khi nào yên tâm&quot;. <a href="/learner/">Sang nhóm: Nemo12 hiểu một learner như thế nào →</a></p>',13)])])}const s=h(i,[["render",a]]);export{k as __pageData,s as default};
